static vec2 hor = vec2 ((1.0/uTexSize.x), 0.0 );
static vec2 ver = vec2 ( 0.0 , (1.0/uTexSize.y));
static mat2 rot45 = mat2(0.7,0.7,-0.7,0.7);
vec2 rs, rs0, uv2, uv3,uv4,dz;
vec3 noise, ret1, neu;
#define GP GetPixel
uv1= multiply(uv1,rot45);
dz = multiply(dz ,rot45);
vec2 uv6 = sin(10.0 * uv1+dz * 12.0 + uTime*.2);
vec3 mus = .06/length(uv6) * (1.0 + length(dz)*length(uTexSize.xy)*0.012*( vec2(0.25) + 2.0*GetBlur1(fract(1-2*uv)).xy));
ret = sqrt(ret1)*(.1+rand_preset.z*0.4+8*mus*clamp01(1.0 - rad));
ret = vec3( 1.0 ) - exp(-ret*1.3);
//ret = GetPixel(uv0);
//MilkDrop3 Solarize Mode:
ret = ret*(1.0 - ret) * 4.0;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  static vec2 center = vec2(.5,.2+rand_preset.x*0.4);
vec2 uv1 = (uv-center );
ret1 = 0;
int anz = 3;
int n = 0;
dz=0;
while (n < anz) {
float dist = 1.0 - fract(1.0/anz*n); //evtl sqrt !;
float inten =  clamp01(1.0 - dist);
uv3 = .5*anz*uv1*dist + center;
float mask = (uv3.x>0) && (uv3.x<1) &&  (uv3.y>0) && (uv3.y<1);
mask = max(0.5,mask);
dz.x += inten*(lum(GP(uv3+hor))- lum(GP (uv3-hor)));
dz.y += inten*(lum(GP(uv3+ver))- lum(GP (uv3-ver)));
dz *= length(dz)>length((vec2(1.0)/uTexSize)) * 8.0;
neu = max(GP(uv3+dz*0.1*inten),GetBlur3(uv3).xy*.50*rand_preset.y);
ret1 = max(ret1,neu*inten*mask);
n++;
  fragColor = vec4(ret, 1.0);
}

